def make_history(anchors, noise=.012, seed=7):
    rng = random.Random(seed)
    # months Jan 2019 .. Oct 2026
    out = []
    months = []
    for y in range(2019, 2027):
        for m in range(1, 13):
            if y == 2026 and m > 10:
                break
            months.append((y, m))
    for i, (y, m) in enumerate(months):
        t = (y - anchors[0][0]) * 12 + (m - anchors[0][1])
        # find bracketing anchors
        lo = anchors[0]
        hi = anchors[-1]
        for a in anchors:
            if (a[0], a[1]) <= (y, m):
                lo = a
            if (a[0], a[1]) >= (y, m):
                hi = a
                break
        if hi[0] == lo[0] and hi[1] == lo[1]:
            val = lo[2]
        else:
            t0 = (lo[0] - anchors[0][0]) * 12 + (lo[1] - anchors[0][1])
            t1 = (hi[0] - anchors[0][0]) * 12 + (hi[1] - anchors[0][1])
            frac = (t - t0) / max(1, t1 - t0)
            val = lo[2] + (hi[2] - lo[2]) * frac
        # gentle seasonality + noise, keep positive
        season = 1 + 0.015 * math.sin((m - 1) / 12 * 2 * math.pi)
        val = max(0.01, val * season * (1 + rng.uniform(-noise, noise)))
        out.append(round(val, 3))
    return {"start": "2019-01", "values": out, "labels": [f"{y}-{m:02d}" for y, m in months]}


for i, t in enumerate(TOPICS):
    t["history"] = make_history(t["history_anchors"], seed=11 + i)
    del t["history_anchors"]

